create function public.runtime_pending_provisioning(p jsonb)returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(id),'[]')from(select pr.id from private.provisioning pr join public.memberships actor on actor.id=pr.actor_id where pr.state in('reserved','auth_created','failed')and actor.active and(pr.lease_until is null or pr.lease_until<now())order by pr.updated_at limit 20)x$$;
create function public.runtime_upload_candidates(p jsonb)returns jsonb language sql stable security definer set search_path='' as $$select coalesce(jsonb_agg(x),'[]')from(select id,object_key,checksum,declared_type,school_id,created_at from public.attachments a where a.state='quarantined'and a.created_at<now()-interval '5 minutes'and not exists(select 1 from public.outbox where dedup_key='scan:'||a.id)order by a.created_at limit 20)x$$;
create function public.runtime_reconcile_upload(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare a public.attachments;begin select * into a from public.attachments where id=(p->>'id')::uuid and state='quarantined'for update;if not found then return;end if;if (p->>'exists')::boolean then insert into public.outbox(school_id,kind,dedup_key,payload)values(a.school_id,'scan','scan:'||a.id,jsonb_build_object('attachmentId',a.id,'objectKey',a.object_key,'checksum',a.checksum,'type',a.declared_type))on conflict do nothing;elsif a.created_at<now()-interval '24 hours'then update public.attachments set state='deleted',charged=false where id=a.id;end if;end$$;
create function public.runtime_deleted_export(p jsonb)returns void language sql security definer set search_path='' as $$update public.report_exports set object_key=null where object_key=p->>'objectKey'and expires_at<=now()$$;
create or replace function public.runtime_cleanup(p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare keys jsonb;begin update private.support_sessions set ended_at=now()where ended_at is null and expires_at<=now();update public.report_exports set status='expired'where expires_at<=now();select coalesce(jsonb_agg(object_key),'[]')into keys from public.report_exports where expires_at<=now()and object_key is not null;update private.sessions set revoked_at=now()where revoked_at is null and expires_at<=now();return keys;end$$;
revoke execute on function public.runtime_pending_provisioning(jsonb),public.runtime_upload_candidates(jsonb),public.runtime_reconcile_upload(jsonb),public.runtime_deleted_export(jsonb)from public,anon,authenticated;grant execute on function public.runtime_pending_provisioning(jsonb),public.runtime_upload_candidates(jsonb),public.runtime_reconcile_upload(jsonb),public.runtime_deleted_export(jsonb)to service_role;
